#include <stdint.h>

/* Registros de reloj (RCC) */
#define RCC_AHB2ENR     (*(volatile uint32_t *)(0x40021000UL + 0x4CUL))

/* Registros de GPIOA (LED LD2 en PA5) */
#define GPIOA_MODER     (*(volatile uint32_t *)(0x48000000UL + 0x00UL))
#define GPIOA_BSRR      (*(volatile uint32_t *)(0x48000000UL + 0x18UL))

/* Registros de GPIOC (Botón B1 en PC13) */
#define GPIOC_MODER     (*(volatile uint32_t *)(0x48000800UL + 0x00UL))
#define GPIOC_IDR       (*(volatile uint32_t *)(0x48000800UL + 0x10UL))

int main(void)
{
    /* 1. Habilitar reloj de GPIOA (Bit 0) y GPIOC (Bit 2) */
    RCC_AHB2ENR |= (1UL << 0) | (1UL << 2);

    /* 2. Configurar PA5 como salida digital: bits [11:10] = 01 */
    GPIOA_MODER &= ~(3UL << 10);
    GPIOA_MODER |=  (1UL << 10);

    /* 3. Configurar PC13 como entrada digital: bits [27:26] = 00 */
    GPIOC_MODER &= ~(3UL << 26);

    while (1) {
        /* 4. Leer bit 13 de GPIOC_IDR (botón B1 es activo en bajo: 0 = presionado) */
        if ((GPIOC_IDR & (1UL << 13)) == 0U) {
            /* Botón presionado -> Encender LD2 (PA5 = HIGH) */
            GPIOA_BSRR = (1UL << 5);
        } else {
            /* Botón suelto -> Apagar LD2 (PA5 = LOW) */
            GPIOA_BSRR = (1UL << 21);
        }
    }
}
